274	    public static long lcm(long u, long v) {
275	        if (u == 0 || v == 0) return 0;
276	        long q = u / gcd(u, v);
277	        if (q == java.lang.Long.MIN_VALUE || v == java.lang.Long.MIN_VALUE) throw overflow();
278	        try {
279	            return Math.multiplyExact(Math.abs(q), Math.abs(v));
280	        }
281	        catch (ArithmeticException e) {
282	            throw overflow();
283	        }
284	    }
