286	    public static long gcd(long u, long v) {
287	        /* Thank you, Wikipedia. */
288	        /* But is this faster than just dividing on a modern
289	     * architecture? -Jan */
290	        long k = 0;
291	        if (u <= 0) {
292	            if (u == 0) return (v < 0) ? -v : v;
293	            u = -u;
294	        }
295	        if (v <= 0) {
296	            if (v == 0) return u;
297	            v = -v;
298	        }
299	        long uv = u | v;
300	        for (; (uv & 1) == 0; uv >>>= 1) { /* While both u and v are even */
301	            k++;  /* Store their common power of 2 */
302	        }
303	        /* At this point either u or v (or both) is odd */
304	        u >>>= k;
305	        for (; (u & 1) == 0; u >>>= 1) {
306	        } /* Divide u by 2 until odd. */
307	        v >>>= k;
308	        for (; (v & 1) == 0; v >>>= 1) {
309	        } /* Divide v by 2 until odd. */
310	        while (true) {
311	            /* u and v are both odd */
312	            if (u >= v) {
313	                u = (u - v) >>> 1;
314	                if (u == 0) return (v << k);
315	                for (; (u & 1) == 0; u >>>= 1) {
316	                } /* Divide u by 2 until odd. */
317	            } else {
318	                /* u and v both odd, v > u */
319	                v = (v - u) >>> 1;
320	                for (; (v & 1) == 0; v >>>= 1) {
321	                } /* Divide v by 2 until odd. */
322	            }
323	        }
324	    }
