326	    public static long choose(long n, long k) {
327	        if (k > n / 2) k = n - k;
328	        if (k == 0) return 1;
329	        if (k == 1) return n;
330	        // k <= n/2
331	        // Will multiply (k) terms, n-k+1 through n-k+k
332	        // will divide by k terms, 1 through k
333	        // Note that if we divide after multiplying, it will
334	        // always be evenly divisible.
335	        // Proof: when we divide by k, we've multiplied by k consecutive integers,
336	        // at least one of which will be a multiple of k.
337	        long accum = 1;
338	        for (long j = 1; j <= k; j++) {
339	            long m = n - k + j;
340	            accum = accum * m;
341	            accum = accum / j;
342	        }
343	        return accum;
344	    }
