346	    public static long mod(long xi, long yi) {
347	        long ri = xi % yi;
348	        if (ri == 0) return 0;
349	
350	        if (yi > 0) {
351	            if (xi >= 0) return ri;
352	            return ri + yi;
353	        } else {
354	            if (xi >= 0) return ri + yi;
355	            return ri;
356	        }
357	    }
