359	    public static long pow(long x, long y) {
360	        long r = 1;
361	        while (y > 0) {
362	            if ((y & 1) != 0) {
363	                r *= x;
364	                y--;
365	            }
366	            x *= x;
367	            y >>>= 1;
368	        }
369	        return r;
370	    }
